/**
 * Copies the art the app uses from `art/source` (the asset pack, regenerated by `gen.py`) into
 * `app/src/assets/game`, where Vite fingerprints it and the service worker caches it with the app shell.
 * Run after changing the pack: `pnpm --filter @ld/app-pixel-pitch art:build`. The output is committed, so CI and
 * fresh clones need neither Python nor this step.
 */
import { spawnSync } from 'node:child_process'
import { cpSync, existsSync, mkdirSync, readdirSync, readFileSync, rmSync, writeFileSync } from 'node:fs'
import { createRequire } from 'node:module'
import path from 'node:path'
import process from 'node:process'

const here = path.dirname(new URL(import.meta.url).pathname)
const source = path.join(here, 'source')
const target = path.resolve(here, '../app/src/assets/game')

// Only what the screens draw. Sound effects are converted below; the music is optional and left out for now.
const FOLDERS = [
  'sprites/players',
  'sprites/crests',
  'sprites/flags',
  'sprites/pitch',
  'sprites/icons',
  'sprites/badges',
  'sprites/cards',
  'sprites/packs',
  'sprites/text',
  'sprites/ui',
  'sprites/club',
]

if (!existsSync(source)) {
  console.error(`No asset pack at ${source}.`)
  process.exit(1)
}

rmSync(target, { recursive: true, force: true })
for (const folder of FOLDERS) {
  const destination = path.join(target, folder.replace(/^sprites\//, ''))
  mkdirSync(path.dirname(destination), { recursive: true })
  cpSync(path.join(source, folder), destination, { recursive: true, filter: file => !file.endsWith('.DS_Store') })
}
// Re-indented to the repo's JSON style, so lint and the art build agree.
writeFileSync(path.join(target, 'palette.json'), `${JSON.stringify(JSON.parse(readFileSync(path.join(source, 'palette/palette.json'), 'utf8')), null, 2)}\n`)
console.log(`Copied ${FOLDERS.length} folders of art into ${path.relative(process.cwd(), target)}.`)

// Sound effects: AAC in .m4a, mono, which every browser and both phones play, a fraction of the size of the WAVs.
// Needs ffmpeg (Homebrew) or macOS's afconvert.
const sfx = path.join(source, 'audio/sfx')
const audio = path.join(target, 'audio')
mkdirSync(audio, { recursive: true })
const hasFfmpeg = spawnSync('ffmpeg', ['-version']).status === 0
let converted = 0
for (const file of readdirSync(sfx).filter(name => name.endsWith('.wav'))) {
  const out = path.join(audio, file.replace(/\.wav$/, '.m4a'))
  const input = path.join(sfx, file)
  const result = hasFfmpeg
    ? spawnSync('ffmpeg', ['-loglevel', 'error', '-y', '-i', input, '-ac', '1', '-c:a', 'aac', '-b:a', '64k', '-map_metadata', '-1', '-fflags', '+bitexact', out])
    : spawnSync('afconvert', ['-f', 'm4af', '-d', 'aac', '-c', '1', '-b', '64000', input, out])
  if (result.status !== 0) {
    console.error(`Could not convert ${file}: install ffmpeg (brew install ffmpeg).`)
    process.exit(1)
  }
  converted++
}
console.log(`Converted ${converted} sound effects into ${path.relative(process.cwd(), audio)}.`)

// Native icon and launch screen, from the pack's app art. The splash is a full-screen portrait picture (grass along
// the bottom), so it goes in as it is: Capacitor's asset tool expects a square splash and would crop the grass off.
// The app is iPhone-only, so one portrait image (1170×2532, used at 3x) fits every screen with aspect-fill.
const ios = path.resolve(here, '../app/ios/App/App/Assets.xcassets')
if (existsSync(ios)) {
  const iconSet = path.join(ios, 'AppIcon.appiconset')
  cpSync(path.join(source, 'app/icon_1024.png'), path.join(iconSet, 'AppIcon-512@2x.png'))

  const splashSet = path.join(ios, 'Splash.imageset')
  for (const file of readdirSync(splashSet).filter(name => name.endsWith('.png')))
    rmSync(path.join(splashSet, file))
  cpSync(path.join(source, 'app/splash_1170x2532.png'), path.join(splashSet, 'splash.png'))
  writeFileSync(path.join(splashSet, 'Contents.json'), `${JSON.stringify({
    images: [{ idiom: 'universal', filename: 'splash.png', scale: '3x' }],
    info: { version: 1, author: 'xcode' },
  }, null, 2)}\n`)
  console.log('Wrote the iOS app icon and launch screen.')
}

// Android: launcher icons (adaptive foreground on the navy, plus legacy square and round icons for Android 7) and
// splash drawables. Resized with nearest-neighbour so the pixel art stays sharp; Capacitor's asset tool smooths it.
const android = path.resolve(here, '../app/android/app/src/main/res')
if (existsSync(android)) {
  const sharp = createRequire(path.resolve(here, '../app/package.json'))('sharp') as typeof import('sharp')
  const NAVY = '#1b1f3b'
  const DENSITIES = { mdpi: 1, hdpi: 1.5, xhdpi: 2, xxhdpi: 3, xxxhdpi: 4 } as const
  const nearest = { kernel: 'nearest' } as const
  const icon = path.join(source, 'app/icon_1024.png')
  const foreground = path.join(source, 'app/icon_android_foreground_432.png')

  writeFileSync(path.join(android, 'values/ic_launcher_background.xml'), `<?xml version="1.0" encoding="utf-8"?>\n<resources>\n    <color name="ic_launcher_background">${NAVY}</color>\n</resources>\n`)

  for (const [density, scale] of Object.entries(DENSITIES)) {
    const dir = path.join(android, `mipmap-${density}`)
    const legacy = Math.round(48 * scale)
    await sharp(foreground).resize(Math.round(108 * scale), Math.round(108 * scale), nearest).png().toFile(path.join(dir, 'ic_launcher_foreground.png'))
    await sharp(icon).resize(legacy, legacy, nearest).png().toFile(path.join(dir, 'ic_launcher.png'))
    const circle = Buffer.from(`<svg width="${legacy}" height="${legacy}"><circle cx="${legacy / 2}" cy="${legacy / 2}" r="${legacy / 2}"/></svg>`)
    await sharp(icon).resize(legacy, legacy, nearest).composite([{ input: circle, blend: 'dest-in' }]).png().toFile(path.join(dir, 'ic_launcher_round.png'))
  }

  // The splash is a tall portrait picture. Widen it by repeating its edge columns (plain sky above, grass stripes
  // below), then crop each drawable to its own shape, so no screen shows a cut-off edge or stretched pixels.
  const splash = path.join(source, 'app/splash_1170x2532.png')
  const { width = 0, height = 0 } = await sharp(splash).metadata()
  const side = Math.ceil((height - width) / 2)
  const square = await sharp(splash).extend({ left: side, right: side, extendWith: 'copy' }).png().toBuffer()
  for (const folder of readdirSync(android).filter(name => /^drawable(-(port|land)-\w+)?$/.test(name))) {
    const file = path.join(android, folder, 'splash.png')
    if (!existsSync(file))
      continue
    const { width: w = 0, height: h = 0 } = await sharp(file).metadata()
    const out = await sharp(square).resize(w, h, { ...nearest, fit: 'cover', position: 'centre' }).png().toBuffer()
    writeFileSync(file, out)
  }
  console.log('Wrote the Android launcher icons and splash.')
}

// Web: favicon, Apple touch icon and the PWA's install icons. The pack's icon is 32×32 pixel art drawn at 32×, so
// 192 and 512 are whole multiples of its pixels. The maskable icon is the icon at 75% (inside the 80% safe zone),
// widened by repeating its edge pixels (sky above, grass below), so any launcher mask shows a whole scene.
{
  const sharp = createRequire(path.resolve(here, '../app/package.json'))('sharp') as typeof import('sharp')
  const publicDir = path.resolve(here, '../app/public')
  const icon = path.join(source, 'app/icon_1024.png')
  const nearest = { kernel: 'nearest' } as const
  const flat = (size: number, file: string) => sharp(icon).resize(size, size, nearest).png().toFile(path.join(publicDir, file))
  await flat(32, 'favicon.png')
  await flat(180, 'apple-touch-icon.png')
  await flat(192, 'pwa-192x192.png')
  await flat(512, 'pwa-512x512.png')
  const inner = await sharp(icon).resize(384, 384, nearest).png().toBuffer()
  await sharp(inner).extend({ top: 64, bottom: 64, left: 64, right: 64, extendWith: 'copy' }).png().toFile(path.join(publicDir, 'maskable-icon-512x512.png'))
  console.log('Wrote the web favicon, touch icon and PWA icons.')
}
